using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using Microsoft.Win32;
namespace FoolLauncher {
 public sealed class SkinLibraryPage {
  readonly Window Window;readonly string Root;readonly SkinStore Store;readonly AccountStore Accounts;readonly SkinUsageStore Usage;readonly Func<Func<CancellationToken,Task>,Task> Runner;readonly Func<bool> Busy;SkinBrowser Browser;bool Online,Visible,Applying;string AccountKey="";
  T Get<T>(string n)where T:class{return Window.FindName(n) as T;}
  public SkinLibraryPage(Window window,string root,AccountStore accounts=null,Func<Func<CancellationToken,Task>,Task> runner=null,Func<bool> busy=null){Window=window;Root=root;Store=new SkinStore(root);Accounts=accounts??new AccountStore(Path.Combine(root,"data"),()=>false);Usage=new SkinUsageStore(root);Runner=runner??(action=>action(CancellationToken.None));Busy=busy??(()=>false);
   Get<Button>("LocalSkinsTab").Click+=(s,e)=>Switch(false);Get<Button>("OnlineSkinsTab").Click+=async(s,e)=>{Switch(true);if(Browser==null)Browser=new SkinBrowser(Window,Root,Store,Status,Refresh);await Browser.Ensure();Browser.SetVisible(Visible&&Online);};
   Get<Button>("ImportSkinButton").Click+=(s,e)=>Import();Get<Button>("RefreshSkinsButton").Click+=(s,e)=>Refresh();Get<Button>("SkinFolderButton").Click+=(s,e)=>Attempt(()=>{Directory.CreateDirectory(Store.Folder);Process.Start(new ProcessStartInfo(Store.Folder){UseShellExecute=true});});
   Window.Closed+=(s,e)=>{if(Browser!=null)Browser.Dispose();};Refresh();Switch(false);
  }
  void Status(string message){Get<TextBlock>("SkinStatus").Text=message;}
  void Attempt(Action action){try{action();}catch(Exception ex){Status(ex.Message);}}
  public void RefreshLanguage(){Refresh();Switch(Online);if(Browser!=null)Browser.RefreshLanguage();}
  public void SetVisible(bool visible){Visible=visible;if(Browser!=null)Browser.SetVisible(visible&&Online);}
  void Switch(bool online){Online=online;Get<FrameworkElement>("LocalSkinsPanel").Visibility=online?Visibility.Collapsed:Visibility.Visible;Get<FrameworkElement>("OnlineSkinsPanel").Visibility=online?Visibility.Visible:Visibility.Collapsed;foreach(var name in new[]{"LocalSkinsTab","OnlineSkinsTab"})Get<Button>(name).SetResourceReference(Control.BackgroundProperty,(name=="OnlineSkinsTab")==online?"Brush.Selection":"Brush.Button");if(Browser!=null)Browser.SetVisible(Visible&&online);if(!online)Refresh();}
  void Import(){var picker=new OpenFileDialog{Title=UiText.T("导入本地皮肤"),Filter=UiText.T("Minecraft 皮肤 PNG|*.png"),Multiselect=true};if(picker.ShowDialog(Window)!=true)return;if(picker.FileNames.Length>100){Status(UiText.T("每次最多导入 100 个皮肤。"));return;}int before=Store.List().Count,failed=0;string last="";foreach(string path in picker.FileNames)try{Store.ImportFile(path);}catch(Exception ex){failed++;last=Path.GetFileName(path)+": "+ex.Message;}Refresh();Status(String.Format(UiText.T("新增 {0} 个皮肤，重复文件自动跳过。"),Store.List().Count-before)+(failed>0?"  "+String.Format(UiText.T("{0} 个未导入：{1}"),failed,last):""));}
  public void Refresh(){AccountKey=CurrentKey();var panel=Get<WrapPanel>("LocalSkinCards");panel.Children.Clear();var skins=Store.List();int shown=0;foreach(var skin in skins){try{panel.Children.Add(Card(skin));shown++;}catch{}}Get<TextBlock>("SkinsEmpty").Visibility=shown==0?Visibility.Visible:Visibility.Collapsed;}
  string CurrentKey(){try{var account=Accounts.Current();return Accounts.Mode()+":"+(account==null?"":account.Id+":"+AccountStore.Text(AccountStore.Object(AccountStore.Object(account.Data,"profile"),"skin"),"url"));}catch{return "";}}
  public void AccountChanged(){if(Visible&&!Applying&&AccountKey!=CurrentKey())Refresh();}
  string ActiveSkin(){try{return Accounts.Mode()=="online"?Usage.Active(Accounts.Current()):"";}catch{return "";}}
  async Task Use(SavedSkin skin){
   if(Applying)return;if(Busy()){Status(UiText.T("请先等待当前任务完成。"));return;}
   try{Accounts.SkinAccount();}catch(Exception ex){Status(ex.Message);return;}
   Applying=true;Refresh();Status(UiText.T("正在向 Minecraft 官方服务应用皮肤…"));
   try{await Runner(async ct=>{try{using(var app=new SkinApplication(Root,Accounts)){string account=await app.Apply(skin,ct);Status(String.Format(UiText.T("已为 {0} 使用此皮肤；之前的皮肤已自动取消使用。下次进入游戏生效。"),account));}}catch(OperationCanceledException){Status(UiText.T("应用已停止，请刷新后确认当前皮肤。"));}catch(Exception ex){Status(ex.Message);}});}finally{Applying=false;Refresh();}
  }
  FrameworkElement Card(SavedSkin skin){
   var content=new StackPanel();var tools=new Grid{Margin=new Thickness(0,0,0,4)};tools.ColumnDefinitions.Add(new ColumnDefinition());tools.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});
   var favorite=IconButton("M 10,1 L 12.8,6.7 L 19,7.6 L 14.5,12 L 15.6,18.2 L 10,15.2 L 4.4,18.2 L 5.5,12 L 1,7.6 L 7.2,6.7 Z",UiText.T(skin.Favorite?"取消星标收藏":"收藏此皮肤"),skin.Name,"Brush.Muted");
   var star=(System.Windows.Shapes.Path)favorite.Content;if(skin.Favorite){star.Fill=new SolidColorBrush(Color.FromRgb(232,198,106));star.Stroke=new SolidColorBrush(Color.FromRgb(176,140,56));}favorite.HorizontalAlignment=HorizontalAlignment.Left;favorite.Click+=(s,e)=>Attempt(()=>{Store.SetFavorite(skin,!skin.Favorite);Refresh();Status(UiText.T(skin.Favorite?"已取消此皮肤的星标收藏。":"已收藏此皮肤，优先显示。"));});tools.Children.Add(favorite);
   var remove=IconButton("M 1,5 L 19,5 M 7,5 L 7,2 L 13,2 L 13,5 M 3,5 L 4,22 L 16,22 L 17,5 M 8,9 L 8,18 M 12,9 L 12,18",UiText.T("删除皮肤"),skin.Name,"Brush.Danger");Grid.SetColumn(remove,1);remove.Click+=(s,e)=>Delete(skin);tools.Children.Add(remove);content.Children.Add(tools);
   var top=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};var image=Store.Image(skin);
   foreach(bool back in new[]{false,true}){var side=new StackPanel{Margin=new Thickness(3,0,3,0)};var pic=new Image{Source=SkinPreview.Render(image,skin.Slim,back),Width=72,Height=130,Stretch=Stretch.Uniform};RenderOptions.SetBitmapScalingMode(pic,BitmapScalingMode.NearestNeighbor);side.Children.Add(pic);var label=new TextBlock{Text=UiText.T(back?"背面":"正面"),TextAlignment=TextAlignment.Center,FontSize=11,Margin=new Thickness(0,6,0,0)};label.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Muted");side.Children.Add(label);top.Children.Add(side);}content.Children.Add(top);
   content.Children.Add(new TextBlock{Text=skin.Name,ToolTip=skin.Name,FontWeight=FontWeights.SemiBold,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(0,12,0,4)});
   var detail=new TextBlock{Text="64×"+skin.Height+(skin.Slim?" · Slim":" · Classic"),FontSize=11};detail.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Muted");content.Children.Add(detail);
   var buttons=new Grid{Margin=new Thickness(0,10,0,0)};for(int col=0;col<5;col++)buttons.ColumnDefinitions.Add(new ColumnDefinition{Width=col==3?new GridLength(1,GridUnitType.Star):GridLength.Auto});
   bool active=ActiveSkin()==skin.Id;var use=new Button{Content=UiText.T(active?"✓ 使用中":"使用"),Padding=new Thickness(7,6,7,6),FontSize=12,Margin=new Thickness(0,0,6,0),IsEnabled=!Applying&&!active,ToolTip=UiText.T("应用到当前微软账号的 Java 版角色")};use.SetResourceReference(Control.BackgroundProperty,active?"Brush.Selection":"Brush.Accent");use.SetResourceReference(Control.ForegroundProperty,active?"Brush.Text":"Brush.AccentText");System.Windows.Automation.AutomationProperties.SetName(use,UiText.T(active?"使用中":"使用皮肤")+" · "+skin.Name);use.Click+=async(s,e)=>await Use(skin);buttons.Children.Add(use);
   var preview=new Button{Content=UiText.T("预览"),Padding=new Thickness(7,6,7,6),FontSize=12,Margin=new Thickness(0,0,6,0)};preview.Click+=(s,e)=>Attempt(()=>Preview(skin));Grid.SetColumn(preview,1);buttons.Children.Add(preview);var export=new Button{Content=UiText.T("导出 PNG"),Padding=new Thickness(7,6,7,6),FontSize=12,Margin=new Thickness(0)};export.Click+=(s,e)=>Attempt(()=>Export(skin));Grid.SetColumn(export,2);buttons.Children.Add(export);
   var rename=IconButton("M 2,11 L 1,15 L 5,14 L 14,5 L 11,2 Z M 9,4 L 12,7",UiText.T("重命名皮肤"),skin.Name,"Brush.Accent");Grid.SetColumn(rename,4);rename.Click+=(s,e)=>Rename(skin);buttons.Children.Add(rename);content.Children.Add(buttons);
   var card=new Border{Child=content,Width=264,Padding=new Thickness(12),CornerRadius=new CornerRadius(9),Margin=new Thickness(0,0,12,12)};card.SetResourceReference(Border.BackgroundProperty,"Brush.Hero");return card;
  }
  Button IconButton(string geometry,string label,string name,string color){var icon=new System.Windows.Shapes.Path{Data=Geometry.Parse(geometry),Width=15,Height=17,Stretch=Stretch.Uniform,StrokeThickness=1.6,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round,StrokeLineJoin=PenLineJoin.Round,Fill=Brushes.Transparent};icon.SetResourceReference(System.Windows.Shapes.Shape.StrokeProperty,color);var button=new Button{Content=icon,Width=26,Height=26,Padding=new Thickness(5),Margin=new Thickness(0),Background=Brushes.Transparent,ToolTip=label};System.Windows.Automation.AutomationProperties.SetName(button,label+" · "+name);return button;}
  void Rename(SavedSkin skin){
   var panel=new StackPanel{Margin=new Thickness(20)};panel.Children.Add(new TextBlock{Text=UiText.T("皮肤名称"),Margin=new Thickness(0,0,0,8)});var input=new TextBox{Text=skin.Name,MaxLength=80,Padding=new Thickness(8,6,8,6)};input.SetResourceReference(Control.BackgroundProperty,"Brush.Base");input.SetResourceReference(Control.ForegroundProperty,"Brush.Text");input.SetResourceReference(TextBox.CaretBrushProperty,"Brush.Text");input.SetResourceReference(Control.BorderBrushProperty,"Brush.Selection");System.Windows.Automation.AutomationProperties.SetName(input,UiText.T("皮肤名称"));panel.Children.Add(input);
   var error=new TextBlock{TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,0)};error.SetResourceReference(TextBlock.ForegroundProperty,"Brush.Error");panel.Children.Add(error);
   var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,14,0,0)};var save=new Button{Content=UiText.T("保存"),Padding=new Thickness(16,8,16,8),Margin=new Thickness(0,0,8,0),IsDefault=true};save.SetResourceReference(Control.BackgroundProperty,"Brush.Accent");save.SetResourceReference(Control.ForegroundProperty,"Brush.AccentText");var cancel=new Button{Content=UiText.T("取消"),Padding=new Thickness(16,8,16,8),Margin=new Thickness(0),IsCancel=true};row.Children.Add(save);row.Children.Add(cancel);panel.Children.Add(row);
   var dialog=new Window{Owner=Window,Title=UiText.T("重命名皮肤"),Content=panel,Width=430,SizeToContent=SizeToContent.Height,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,FontFamily=Window.FontFamily,FontSize=14};dialog.SetResourceReference(Control.BackgroundProperty,"Brush.Panel");dialog.SetResourceReference(Control.ForegroundProperty,"Brush.Text");dialog.Resources[typeof(Button)]=Window.FindResource(typeof(Button));
   save.Click+=(s,e)=>{try{Store.Rename(skin,input.Text);Refresh();Status(UiText.T("皮肤名称已保存。"));dialog.Close();}catch(Exception ex){error.Text=ex.Message;input.Focus();}};cancel.Click+=(s,e)=>dialog.Close();dialog.Loaded+=(s,e)=>{input.Focus();input.SelectAll();};dialog.ShowDialog();
  }
  void Delete(SavedSkin skin){if(Applying){Status(UiText.T("请先等待当前任务完成。"));return;}if(!DeleteConfirmation.Show(Window,UiText.T("删除皮肤"),skin.Name,UiText.T("皮肤图片及其名称、星标记录都会一起移入回收站。"),UiText.T("恢复方法：还原回收站中的 .recycle- 文件夹，将里面的 PNG 和 JSON 移回 data/skins 后刷新列表。")))return;Attempt(()=>{Store.Recycle(skin);Refresh();Status(UiText.T("皮肤已移入 Windows 回收站。"));});}
  void Export(SavedSkin skin){string name=skin.Name;foreach(char c in Path.GetInvalidFileNameChars())name=name.Replace(c,'_');var picker=new SaveFileDialog{Title=UiText.T("导出皮肤 PNG"),FileName=name+".png",Filter="PNG|*.png",DefaultExt=".png"};if(picker.ShowDialog(Window)==true){Store.Export(skin,picker.FileName);Status(UiText.T("皮肤 PNG 已导出。"));}}
  void Preview(SavedSkin skin){var panel=new StackPanel{Margin=new Thickness(24)};var row=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};var image=Store.Image(skin);foreach(bool back in new[]{false,true}){var pic=new Image{Source=SkinPreview.Render(image,skin.Slim,back),Width=180,Height=260,Stretch=Stretch.Uniform,Margin=new Thickness(10)};RenderOptions.SetBitmapScalingMode(pic,BitmapScalingMode.NearestNeighbor);row.Children.Add(pic);}panel.Children.Add(row);panel.Children.Add(new TextBlock{Text=skin.Name,FontSize=20,HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,15,0,12),TextWrapping=TextWrapping.Wrap});var export=new Button{Content=UiText.T("导出 PNG"),HorizontalAlignment=HorizontalAlignment.Center};export.Click+=(s,e)=>Attempt(()=>Export(skin));panel.Children.Add(export);var dialog=new Window{Owner=Window,Title=UiText.T("皮肤预览"),Content=panel,Width=470,Height=460,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner};dialog.SetResourceReference(Control.BackgroundProperty,"Brush.Panel");dialog.SetResourceReference(Control.ForegroundProperty,"Brush.Text");dialog.ShowDialog();}
 }
}
